import{_ as e,o as n,c as s,am as t}from"./chunks/framework._FJXuPhs.js";const I=JSON.parse('{"title":"IO.流","description":"","frontmatter":{"title":"IO.流","excerpt":"这篇文章主要是围绕一些基础知识的内容去对于整个IO体系有一个基础的了解。","date":"2024-01-08 14:07:09","updated":"2024-01-08 14:07:09"},"headers":[],"relativePath":"基础/IO与NIO/IO.流.md","filePath":"基础/IO与NIO/IO.流.md","lastUpdated":null}'),p={name:"基础/IO与NIO/IO.流.md"};function i(l,a,r,o,d,c){return n(),s("div",null,[...a[0]||(a[0]=[t(`<h3 id="_1、基础知识" tabindex="-1">1、基础知识 <a class="header-anchor" href="#_1、基础知识" aria-label="Permalink to &quot;1、基础知识&quot;">​</a></h3><p>参考： <a href="https://javaguide.cn/java/io/io-basis.html" target="_blank" rel="noreferrer">https://javaguide.cn/java/io/io-basis.html</a></p><p>IO 指的是输入和输出（主体是计算机内存）</p><ul><li>输入： 数据输入到计算机内存</li><li>输出：从计算机内存输出到外部设备</li></ul><p>了解 Java IO 流，需要知道四个基本的抽象类基类：</p><ul><li><code>InputStream</code>/<code>Reader</code>: 所有的输入流的基类，前者是字节输入流，后者是字符输入流。</li><li><code>OutputStream</code>/<code>Writer</code>: 所有输出流的基类，前者是字节输出流，后者是字符输出流。</li></ul><p>常用方法建议直接看一下 API 方法</p><p>IO</p><ul><li>字节流 <ul><li>InputStream 字节输入流</li><li>OutputStream 字节输出流</li></ul></li><li>字符流 <ul><li>Reader</li><li>Writer</li></ul></li><li>字节缓冲流 <ul><li>BufferedInputStream（字节缓冲输入流）</li><li>BufferedOutputStream（字节缓冲输出流）</li></ul></li><li>字符缓冲流</li><li>打印流</li><li>随机访问流</li></ul><p>一般来说，我们是建议如果读取文字的时候使用字符流，字符流默认采用的是 <code>Unicode</code> 编码，因此不会出现很明显的输入和输出编码不一致的情况；</p><p>对于音频、图片等建议使用字节流。</p><p>记录一个面试题</p><blockquote><p>常用字符编码所占字节数？&gt;</p></blockquote><p><code>utf8</code> :英文占 1 字节，中文占 3 字节，<code>unicode</code>：任何字符都占 2 个字节，<code>gbk</code>：英文占 1 字节，中文占 2 字节</p><h3 id="_2、缓冲流" tabindex="-1">2、缓冲流 <a class="header-anchor" href="#_2、缓冲流" aria-label="Permalink to &quot;2、缓冲流&quot;">​</a></h3><h4 id="bufferedinputstream-字节缓冲输入流" tabindex="-1">BufferedInputStream（字节缓冲输入流） <a class="header-anchor" href="#bufferedinputstream-字节缓冲输入流" aria-label="Permalink to &quot;BufferedInputStream（字节缓冲输入流）&quot;">​</a></h4><p><code>BufferedInputStream</code> 从源头（通常是文件）读取数据（字节信息）到内存的过程中不会一个字节一个字节的读取，而是会先将读取到的字节存放在缓存区，并从内部缓冲区中单独读取字节。这样大幅减少了 IO 次数，提高了读取效率。</p><p><code>BufferedInputStream</code> 内部维护了一个缓冲区，这个缓冲区实际就是一个字节数组，通过阅读 <code>BufferedInputStream</code> 源码即可得到这个结论。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public</span></span>
<span class="line"><span>class BufferedInputStream extends FilterInputStream {</span></span>
<span class="line"><span>    // 内部缓冲区数组</span></span>
<span class="line"><span>    protected volatile byte buf[];</span></span>
<span class="line"><span>    // 缓冲区的默认大小</span></span>
<span class="line"><span>    private static int DEFAULT_BUFFER_SIZE = 8192;</span></span>
<span class="line"><span>    // 使用默认的缓冲区大小</span></span>
<span class="line"><span>    public BufferedInputStream(InputStream in) {</span></span>
<span class="line"><span>        this(in, DEFAULT_BUFFER_SIZE);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    // 自定义缓冲区大小</span></span>
<span class="line"><span>    public BufferedInputStream(InputStream in, int size) {</span></span>
<span class="line"><span>        super(in);</span></span>
<span class="line"><span>        if (size &lt;= 0) {</span></span>
<span class="line"><span>            throw new IllegalArgumentException(&quot;Buffer size &lt;= 0&quot;);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        buf = new byte[size];</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>缓冲区的大小默认为 <strong>8192</strong> 字节，当然，你也可以通过 <code>BufferedInputStream(InputStream in, int size)</code> 这个构造方法来指定缓冲区的大小。</p><h3 id="_3、io-设计模式" tabindex="-1">3、IO 设计模式 <a class="header-anchor" href="#_3、io-设计模式" aria-label="Permalink to &quot;3、IO 设计模式&quot;">​</a></h3><p>to be contined...</p><h3 id="_4、nio" tabindex="-1">4、NIO <a class="header-anchor" href="#_4、nio" aria-label="Permalink to &quot;4、NIO&quot;">​</a></h3><h4 id="io-模型" tabindex="-1">IO 模型 <a class="header-anchor" href="#io-模型" aria-label="Permalink to &quot;IO 模型&quot;">​</a></h4><p>UNIX 系统下， IO 模型一共有 5 种：<strong>同步阻塞 I/O</strong>、<strong>同步非阻塞 I/O</strong>、<strong>I/O 多路复用</strong>、<strong>信号驱动 I/O</strong> 和<strong>异步 I/O</strong></p><p>参考： <a href="https://javaguide.cn/java/io/io-model.html#java-%E4%B8%AD-3-%E7%A7%8D%E5%B8%B8%E8%A7%81-io-%E6%A8%A1%E5%9E%8B" target="_blank" rel="noreferrer">Java IO 模型详解 | JavaGuide</a></p><p>Java 中 3 种常见 IO 模型</p><ul><li>NIO</li><li>BIO</li><li>AIO</li></ul><h4 id="nio详解" tabindex="-1">NIO详解 <a class="header-anchor" href="#nio详解" aria-label="Permalink to &quot;NIO详解&quot;">​</a></h4><p>to be contined...</p>`,30)])])}const h=e(p,[["render",i]]);export{I as __pageData,h as default};
